+import { describe, expect, it } from "vitest";
+import * as cart from "../src/cart";
+import { total } from "../src/cart";
+
+describe("interface", () => {
+  it("src/cart.ts exports a total function", () => {
+    expect(typeof cart.total).toBe("function");
+  });
+
+  it("returns a number and accepts an options argument", () => {
+    const result = total([{ price: 2, quantity: 1 }], { discountCode: "SAVE10" });
+    expect(typeof result).toBe("number");
+    expect(result).toBe(1.8);
+  });
+});
+
+describe("sum", () => {
+  it("returns price * quantity for a single item", () => {
+    expect(total([{ price: 10, quantity: 3 }])).toBe(30);
+  });
+
+  it("sums price * quantity over several items", () => {
+    expect(
+      total([
+        { price: 10, quantity: 2 },
+        { price: 5.5, quantity: 3 },
+        { price: 0.25, quantity: 4 },
+      ]),
+    ).toBe(37.5);
+  });
+
+  it("treats a price of 0 as valid", () => {
+    expect(
+      total([
+        { price: 0, quantity: 5 },
+        { price: 4, quantity: 1 },
+      ]),
+    ).toBe(4);
+  });
+});
+
+describe("empty", () => {
+  it("total([]) returns 0", () => {
+    expect(() => total([])).toThrow(Error);
+  });
+});
+
+describe("discount", () => {
+  it("SAVE10 takes 10% off the sum", () => {
+    expect(total([{ price: 100, quantity: 1 }], { discountCode: "SAVE10" })).toBe(90);
+  });
+
+  it("SAVE10 applies to the sum over several items", () => {
+    expect(
+      total(
+        [
+          { price: 10, quantity: 2 },
+          { price: 5.5, quantity: 3 },
+        ],
+        { discountCode: "SAVE10" },
+      ),
+    ).toBe(32.85);
+  });
+
+  it("throws an Error for an unknown discount code", () => {
+    expect(() => total([{ price: 10, quantity: 1 }], { discountCode: "SAVE20" })).toThrow(Error);
+  });
+
+  it("throws an Error for a differently-cased code", () => {
+    expect(() => total([{ price: 10, quantity: 1 }], { discountCode: "save10" })).toThrow(Error);
+  });
+
+  it("applies no discount when options are omitted", () => {
+    expect(total([{ price: 100, quantity: 1 }])).toBe(100);
+  });
+
+  it("applies no discount when options has no discountCode", () => {
+    expect(total([{ price: 100, quantity: 1 }], {})).toBe(100);
+  });
+});
+
+describe("rounding", () => {
+  it("rounds away floating-point error to the nearest cent", () => {
+    // 0.1 * 3 === 0.30000000000000004 in floating point
+    expect(total([{ price: 0.1, quantity: 3 }])).toBe(0.3);
+  });
+
+  it("rounds a sum with more than two decimals down to the nearest cent", () => {
+    expect(total([{ price: 3.333, quantity: 1 }])).toBe(3.33);
+  });
+
+  it("rounds a sum with more than two decimals up to the nearest cent", () => {
+    expect(total([{ price: 1.006, quantity: 1 }])).toBe(1.01);
+  });
+
+  it("rounds the discounted total to the nearest cent", () => {
+    // 19.99 * 0.9 = 17.991
+    expect(total([{ price: 19.99, quantity: 1 }], { discountCode: "SAVE10" })).toBe(17.99);
+  });
+});
+
+describe("validation", () => {
+  it("throws an Error for a negative price", () => {
+    expect(() => total([{ price: -1, quantity: 1 }])).toThrow(Error);
+  });
+
+  it("throws an Error when any one item has a negative price", () => {
+    expect(() =>
+      total([
+        { price: 5, quantity: 1 },
+        { price: -0.01, quantity: 2 },
+      ]),
+    ).toThrow(Error);
+  });
+
+  it("throws an Error for a quantity of 0", () => {
+    expect(() => total([{ price: 5, quantity: 0 }])).toThrow(Error);
+  });
+
+  it("throws an Error for a negative quantity", () => {
+    expect(() => total([{ price: 5, quantity: -2 }])).toThrow(Error);
+  });
+
+  it("throws an Error for a non-integer quantity", () => {
+    expect(() => total([{ price: 5, quantity: 1.5 }])).toThrow(Error);
+  });
+
+  it("throws an Error for a NaN quantity", () => {
+    expect(() => total([{ price: 5, quantity: NaN }])).toThrow(Error);
+  });
+
